void encode(wire::Writer& w, const CommandBatch& v) {
  w.varint(10U); w.str(v.label);
  for (const auto& e : v.commands) { w.varint(18U); { const std::size_t s = w.begin_ld(); encode(w, e); w.end_ld(s); } }
}

Status decode(wire::Reader& r, CommandBatch& out) {
  bool has_label = false;
  while (!r.at_end()) {
    std::uint64_t key = 0;
    if (!r.varint(key)) return Status::truncated;
    switch (key) {
      case 10U: {
        if (!r.str(out.label)) return Status::truncated;
        has_label = true;
        break;
      }
      case 18U: {
        auto& e = out.commands.emplace_back();
        { wire::Reader sub; if (!r.ld(sub)) return Status::truncated; if (const Status st = decode(sub, e); st != Status::ok) return st; }
        break;
      }
      default:
        if (!r.skip(key)) return Status::truncated;
        break;
    }
  }
  if (!has_label) return Status::missing_field;
  return Status::ok;
}

RequestBody::Kind RequestBody::kind() const noexcept {
  static constexpr std::array<Kind, 3> kKinds = {Kind::command, Kind::query, Kind::batch};
  return kKinds[v.index()];
}

void encode(wire::Writer& w, const RequestBody& v) {
  switch (v.v.index()) {
    case 0: w.varint(10U); { const std::size_t s = w.begin_ld(); encode(w, std::get<0>(v.v)); w.end_ld(s); } return;
    case 1: w.varint(18U); { const std::size_t s = w.begin_ld(); encode(w, std::get<1>(v.v)); w.end_ld(s); } return;
    case 2: w.varint(26U); { const std::size_t s = w.begin_ld(); encode(w, std::get<2>(v.v)); w.end_ld(s); } return;
    default: return;
  }
}

Status decode(wire::Reader& r, RequestBody& out) {
  bool seen = false;
  while (!r.at_end()) {
    std::uint64_t key = 0;
    if (!r.varint(key)) return Status::truncated;
    switch (key) {
      case 10U: {
        if (seen) return Status::multiple_variants;
        Command e;
        { wire::Reader sub; if (!r.ld(sub)) return Status::truncated; if (const Status st = decode(sub, e); st != Status::ok) return st; }
        out.v.emplace<0>(std::move(e));
        seen = true;
        break;
      }
      case 18U: {
        if (seen) return Status::multiple_variants;
        Query e;
        { wire::Reader sub; if (!r.ld(sub)) return Status::truncated; if (const Status st = decode(sub, e); st != Status::ok) return st; }
        out.v.emplace<1>(std::move(e));
        seen = true;
        break;
      }
      case 26U: {
        if (seen) return Status::multiple_variants;
        CommandBatch e;
        { wire::Reader sub; if (!r.ld(sub)) return Status::truncated; if (const Status st = decode(sub, e); st != Status::ok) return st; }
        out.v.emplace<2>(std::move(e));
        seen = true;
        break;
      }
      default:
        if (!r.skip(key)) return Status::truncated;
        break;
    }
  }
  return seen ? Status::ok : Status::unknown_variant;
}

void encode(wire::Writer& w, const Request& v) {
  w.varint(8U); w.varint(v.seq);
  w.varint(18U); { const std::size_t s = w.begin_ld(); encode(w, v.body); w.end_ld(s); }
  if (v.base_revision.has_value()) { w.varint(24U); w.varint(*v.base_revision); }
  w.varint(32U); w.varint(static_cast<std::uint32_t>(v.origin));
}

Status decode(wire::Reader& r, Request& out) {
  bool has_seq = false;
  bool has_body = false;
  bool has_origin = false;
  while (!r.at_end()) {
    std::uint64_t key = 0;
    if (!r.varint(key)) return Status::truncated;
    switch (key) {
      case 8U: {
        if (!r.varint(out.seq)) return Status::truncated;
        has_seq = true;
        break;
      }
      case 18U: {
        { wire::Reader sub; if (!r.ld(sub)) return Status::truncated; if (const Status st = decode(sub, out.body); st != Status::ok) return st; }
        has_body = true;
        break;
      }
      case 24U: {
        Revision e = 0;
        if (!r.varint(e)) return Status::truncated;
        out.base_revision = std::move(e);
        break;
      }
      case 32U: {
        { std::uint32_t n = 0; if (!r.u32(n)) return Status::bad_value; if (!from_u32(n, out.origin)) return Status::bad_enum; }
        has_origin = true;
        break;
      }
      default:
        if (!r.skip(key)) return Status::truncated;
        break;
    }
  }
  if (!has_seq) return Status::missing_field;
  if (!has_body) return Status::missing_field;
  if (!has_origin) return Status::missing_field;
  return Status::ok;
}

