void encode(wire::Writer& w, const BatchResult& v) {
  for (const auto& e : v.results) { w.varint(10U); { const std::size_t s = w.begin_ld(); encode(w, e); w.end_ld(s); } }
}

Status decode(wire::Reader& r, BatchResult& out) {
  while (!r.at_end()) {
    std::uint64_t key = 0;
    if (!r.varint(key)) return Status::truncated;
    switch (key) {
      case 10U: {
        auto& e = out.results.emplace_back();
        { wire::Reader sub; if (!r.ld(sub)) return Status::truncated; if (const Status st = decode(sub, e); st != Status::ok) return st; }
        break;
      }
      default:
        if (!r.skip(key)) return Status::truncated;
        break;
    }
  }
  return Status::ok;
}

void encode(wire::Writer& w, const EngineError& v) {
  w.varint(8U); w.varint(static_cast<std::uint32_t>(v.code));
  w.varint(18U); w.str(v.message);
  if (v.command_index.has_value()) { w.varint(24U); w.varint(*v.command_index); }
  if (v.layer.has_value()) { w.varint(34U); w.str(*v.layer); }
  if (v.path.has_value()) { w.varint(42U); w.str(*v.path); }
  if (v.item.has_value()) { w.varint(50U); w.str(*v.item); }
  if (v.detail.has_value()) { w.varint(58U); w.str(*v.detail); }
}

Status decode(wire::Reader& r, EngineError& out) {
  bool has_code = false;
  bool has_message = false;
  while (!r.at_end()) {
    std::uint64_t key = 0;
    if (!r.varint(key)) return Status::truncated;
    switch (key) {
      case 8U: {
        { std::uint32_t n = 0; if (!r.u32(n)) return Status::bad_value; if (!from_u32(n, out.code)) return Status::bad_enum; }
        has_code = true;
        break;
      }
      case 18U: {
        if (!r.str(out.message)) return Status::truncated;
        has_message = true;
        break;
      }
      case 24U: {
        std::uint32_t e = 0;
        if (!r.u32(e)) return Status::bad_value;
        out.command_index = std::move(e);
        break;
      }
      case 34U: {
        LayerId e;
        if (!r.str(e)) return Status::truncated;
        out.layer = std::move(e);
        break;
      }
      case 42U: {
        PropPath e;
        if (!r.str(e)) return Status::truncated;
        out.path = std::move(e);
        break;
      }
      case 50U: {
        ItemId e;
        if (!r.str(e)) return Status::truncated;
        out.item = std::move(e);
        break;
      }
      case 58U: {
        std::string e;
        if (!r.str(e)) return Status::truncated;
        out.detail = std::move(e);
        break;
      }
      default:
        if (!r.skip(key)) return Status::truncated;
        break;
    }
  }
  if (!has_code) return Status::missing_field;
  if (!has_message) return Status::missing_field;
  return Status::ok;
}

Outcome::Kind Outcome::kind() const noexcept {
  static constexpr std::array<Kind, 4> kKinds = {Kind::command, Kind::query, Kind::batch, Kind::error};
  return kKinds[v.index()];
}

void encode(wire::Writer& w, const Outcome& v) {
  switch (v.v.index()) {
    case 0: w.varint(10U); { const std::size_t s = w.begin_ld(); encode(w, std::get<0>(v.v)); w.end_ld(s); } return;
    case 1: w.varint(18U); { const std::size_t s = w.begin_ld(); encode(w, std::get<1>(v.v)); w.end_ld(s); } return;
    case 2: w.varint(26U); { const std::size_t s = w.begin_ld(); encode(w, std::get<2>(v.v)); w.end_ld(s); } return;
    case 3: w.varint(34U); { const std::size_t s = w.begin_ld(); encode(w, std::get<3>(v.v)); w.end_ld(s); } return;
    default: return;
  }
}

