template <class M>
Status roundtrip(std::span<const std::uint8_t> bytes, std::vector<std::uint8_t>& out) {
  M m{};
  wire::Reader r(bytes);
  if (const Status st = decode(r, m); st != Status::ok) return st;
  wire::Writer w;
  encode(w, m);
  out = w.take();
  return Status::ok;
}
